static const size_t qks_keycodes_n = sizeof(qks_keycodes)/sizeof(qks_keycodes[0]);

// Lookup por name. Retorna value en [0..0xFFFF], o -1 si no existe.
// Linear scan sobre ~800 entries. Compile-time, cero impacto runtime.
static inline int32_t qks_lookup_keycode(const char *name) {
    for (size_t i = 0; i < qks_keycodes_n; i++) {
        if (strcmp(qks_keycodes[i].name, name) == 0)
            return (int32_t)qks_keycodes[i].value;
    }
    return -1;
}
